// Tests anonymous types
using System;
using System.Collections;

public class Test
{
	static int Main ()
	{
		var v = new { Foo = "Bar", Baz = 42 };

		if (v.Foo != "Bar")
			return 1;
		if (v.Baz != 42)
			return 2;

		return 0;
	}
}

// Tests anonymous types initialized with local variables
using System;
using System.Collections;

public class Test
{
	static object TestA (string s)
	{
		return new { s };
	}

	static int Main ()
	{
		string Foo = "Bar";
		int Baz = 42;
		var v = new { Foo, Baz };

		if (v.Foo != "Bar")
			return 1;
		if (v.Baz != 42)
			return 2;

		if (!TestA ("foo").Equals (new { s = "foo" }))
			return 3;

		Console.WriteLine ("OK");
		return 0;
	}
}

